#pragma once
static void checkVisibleCleanup(App& app,const std::string& dir){
 auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("visible cleanup: "+why);};int cases=0;auto& s=app.s;
 for(double turn:{0.,.7})for(double mirror:{-1.,1.})for(int selection:{0,1}){Document d;d.setDefaultBondLength(30);auto pose=[&](Vec2 p){p.x*=mirror;return mechanism::step_detail::rotate(p,turn)+Vec2(150,150);};std::vector<ObjectId> ring;double radius=30/(2*std::sin(3.141592653589793/5));for(int i=0;i<5;++i){ObjectId id;double a=-3.141592653589793/2+i*6.283185307179586/5;d.addAtom(pose(Vec2(radius*std::cos(a),radius+radius*std::sin(a))),6,&id);ring.push_back(id);}for(int i=0;i<5;++i)d.addBond(ring[i],ring[(i+1)%5],nullptr);
 ObjectId ph,c,o,oh,co,ch;d.addAtom(pose(Vec2(-26,-15)),6,&ph);require(nicknames::apply(d,ph,"Ph").ok(),"create actual collapsed phenyl");d.addBond(ring[0],ph,nullptr);d.addAtom(pose(Vec2(18,-24)),6,&c);d.addAtom(pose(Vec2(4,-51)),8,&o);d.addAtom(pose(Vec2(48,-22)),8,&oh);d.addBond(ring[0],c,nullptr);d.addBond(c,o,&co);d.setBondOrder(co,BondOrder::Double);d.addBond(c,oh,&ch);auto sem=d.atoms().alive(oh)->semantics;sem.implicitHydrogens=1;d.setAtomSemantics(oh,sem);for(auto id:{c,o,oh})d.extensions(ObjectRef(ObjectKind::Atom,id)).set("studio.color",std::to_string(0xe31a1cff));
 require(studio_fragment_mass::weights(d).at(ph)==0,"collapsed Ph has zero layout weight");auto actualFormula=studio::analyze(d,{{ObjectKind::Atom,ring[0]}});require(actualFormula.valid&&actualFormula.averageMass>150,"real chemical mass still includes phenyl");
 s.cancel();s.doc=d;s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());if(selection==0)for(auto id:{c,o,oh})s.selected.emplace_back(ObjectKind::Atom,id);else for(auto id:{co,ch})s.selected.emplace_back(ObjectKind::Bond,id);s.refresh();auto before=s.doc.digest();if(cases==0){s.fit();app.invalidate();app.screenshot(dir+"/visible-cleanup-before.png");}app.chemistryAction("clean");require(s.doc.digest()!=before,"actual local cleanup succeeds: "+app.status);
 for(auto id:ring)require(s.doc.atoms().alive(id)->position==d.atoms().alive(id)->position,"unselected cyclopentane stays exact");require(s.doc.atoms().alive(ph)->position==d.atoms().alive(ph)->position&&s.doc.atomLabel(ph)=="Ph","unselected phenyl label stays exact");auto stem=s.doc.atoms().alive(c)->position-s.doc.atoms().alive(ring[0])->position,old=d.atoms().alive(c)->position-d.atoms().alive(ring[0])->position;require(dot(stem,old)/(length(stem)*length(old))>.999999,"COOH stem keeps its original outward direction");require(std::abs(length(stem)-30)<1e-5,"attachment length normalized");
 for(auto a:{c,o,oh})for(auto bid:s.doc.incidentBonds(a)){auto b=s.doc.bonds().alive(bid);for(int i=0;i<5;++i){auto x=ring[i],y=ring[(i+1)%5];if(b->beginAtom==x||b->beginAtom==y||b->endAtom==x||b->endAtom==y)continue;require(!mechanism::step_detail::segmentsCross(s.doc.atoms().alive(b->beginAtom)->position,s.doc.atoms().alive(b->endAtom)->position,s.doc.atoms().alive(x)->position,s.doc.atoms().alive(y)->position),"cleaned red branch never crosses a ring edge");}}
 require(studio::analyze(s.doc,{{ObjectKind::Atom,ring[0]}}).plain==actualFormula.plain,"chemical formula unchanged");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"single atomic undo redo");if(cases==0){s.selected.clear();s.fit();app.invalidate();app.screenshot(dir+"/visible-cleanup-after.png");require(s.save(dir+"/visible-cleanup-after.cdxml",true).ok(),"save corrected example");}++cases;
 }
 std::ofstream(dir+"/visible-cleanup-checks.json")<<"{\"cases\":"<<cases<<",\"partial_atoms_and_bonds\":true,\"stem_direction\":true,\"unselected_fixed\":true,\"no_ring_crossing\":true,\"abbreviation_layout_weight_zero\":true,\"real_formula_mass_preserved\":true,\"undo_redo\":true}";
}
